commands.command:
python3 - <<'PY'
from pathlib import Path
p = Path('src/climate/output/OutputTypes.h')
s = p.read_text()
needle = '''enum class OutputSource : std::uint8_t {
  None = 0U,
  Climate,
  Schedule,
  Manual,
  Safety,
  Lifecycle,
  Maintenance,
};
'''
replacement = needle + '''
enum class OutputReason : std::uint8_t {
  None = 0U,
  ClimateDecision,
  ScheduleRequest,
  ManualRequest,
  ThermalSafety,
  LifecyclePolicy,
  FaultContainment,
  MaintenanceRequest,
};
'''
assert needle in s and 'enum class OutputReason' not in s
p.write_text(s.replace(needle, replacement, 1))
contracts = '''#pragma once

#include "climate/output/OutputTypes.h"

#include <array>
#include <cstdint>

namespace growbox::app::output {

struct IntentMetadata {
  std::uint64_t sequence = 0U;
  std::uint64_t monotonic_ms = 0U;
  OutputSource source = OutputSource::None;
  OutputReason reason = OutputReason::None;
};

struct EndpointIntent {
  OutputEndpointId endpoint = kInvalidOutputEndpoint;
  NormalizedOutputLevel level = 0.0F;
};

constexpr bool endpointIntentActive(const EndpointIntent& intent) noexcept {
  return isValidOutputEndpoint(intent.endpoint);
}

constexpr bool setEndpointIntent(EndpointIntent& intent, OutputEndpointId endpoint,
                                 NormalizedOutputLevel level) noexcept {
  if (!isValidOutputEndpoint(endpoint)) {
    intent = {};
    return false;
  }
  intent.endpoint = endpoint;
  intent.level = level;
  return true;
}

struct ControlIntent {
  IntentMetadata metadata{};
  std::array<EndpointIntent, kOutputEndpointCapacity> endpoints{};
};

struct ScheduleIntent {
  IntentMetadata metadata{};
  std::array<EndpointIntent, kOutputEndpointCapacity> endpoints{};
};

struct ManualIntent {
  IntentMetadata metadata{};
  std::array<EndpointIntent, kOutputEndpointCapacity> endpoints{};
};

enum class SafetyConstraint : std::uint8_t { Allow = 0U, ForceOff, ForceOn, Inhibit };

struct SafetyEndpointConstraint {
  OutputEndpointId endpoint = kInvalidOutputEndpoint;
  SafetyConstraint constraint = SafetyConstraint::Allow;
  OutputReason reason = OutputReason::None;
};

constexpr bool safetyConstraintActive(const SafetyEndpointConstraint& constraint) noexcept {
  return isValidOutputEndpoint(constraint.endpoint);
}

constexpr bool setSafetyConstraint(SafetyEndpointConstraint& target, OutputEndpointId endpoint,
                                   SafetyConstraint constraint, OutputReason reason) noexcept {
  if (!isValidOutputEndpoint(endpoint)) {
    target = {};
    return false;
  }
  target.endpoint = endpoint;
  target.constraint = constraint;
  target.reason = reason;
  return true;
}

struct SafetyEnvelope {
  IntentMetadata metadata{};
  std::array<SafetyEndpointConstraint, kOutputEndpointCapacity> endpoints{};
};

} // namespace growbox::app::output
'''
Path('src/climate/output/OutputIntents.h').write_text(contracts)
test = '''#include "climate/output/OutputIntents.h"

#include <cassert>
#include <type_traits>

using namespace growbox::app::output;

static_assert(std::is_trivially_copyable_v<IntentMetadata>);
static_assert(std::is_trivially_copyable_v<EndpointIntent>);
static_assert(std::is_trivially_copyable_v<ControlIntent>);
static_assert(std::is_trivially_copyable_v<ScheduleIntent>);
static_assert(std::is_trivially_copyable_v<ManualIntent>);
static_assert(std::is_trivially_copyable_v<SafetyEndpointConstraint>);
static_assert(std::is_trivially_copyable_v<SafetyEnvelope>);
static_assert(std::is_standard_layout_v<SafetyEnvelope>);

int main() {
  ControlIntent control{};
  ScheduleIntent schedule{};
  ManualIntent manual{};
  SafetyEnvelope safety{};
  for (const auto& item : control.endpoints) assert(!endpointIntentActive(item));
  for (const auto& item : schedule.endpoints) assert(!endpointIntentActive(item));
  for (const auto& item : manual.endpoints) assert(!endpointIntentActive(item));
  for (const auto& item : safety.endpoints) assert(!safetyConstraintActive(item));

  EndpointIntent endpoint{};
  assert(!setEndpointIntent(endpoint, kInvalidOutputEndpoint, 1.0F));
  assert(!endpointIntentActive(endpoint));
  assert(setEndpointIntent(endpoint, 1U, 0.5F));
  assert(endpointIntentActive(endpoint));
  assert(endpoint.endpoint == 1U);
  assert(endpoint.level == 0.5F);

  SafetyEndpointConstraint rule{};
  assert(setSafetyConstraint(rule, 2U, SafetyConstraint::ForceOn, OutputReason::ThermalSafety));
  assert(safetyConstraintActive(rule));
  assert(rule.constraint == SafetyConstraint::ForceOn);
  auto copy = rule;
  assert(copy.endpoint == rule.endpoint);
  copy = {};
  assert(!safetyConstraintActive(copy));
  return 0;
}
'''
Path('test/test_output_intents').mkdir(parents=True, exist_ok=True)
Path('test/test_output_intents/test_main.cpp').write_text(test)
p = Path('test/host/CMakeLists.txt')
s = p.read_text()
anchor = 'add_executable(\n  output_types_tests'
block = '''add_executable(
  output_intents_tests
  "${PROJECT_ROOT}/test/test_output_intents/test_main.cpp"
)
target_include_directories(output_intents_tests PRIVATE "${PROJECT_ROOT}/src")
target_compile_features(output_intents_tests PRIVATE cxx_std_17)
target_compile_options(output_intents_tests PRIVATE -Wall -Wextra -Wpedantic)

'''
assert anchor in s and 'output_intents_tests' not in s
s = s.replace(anchor, block + anchor, 1)
test_anchor = 'add_test(NAME output_types_tests COMMAND output_types_tests)'
s = s.replace(test_anchor, 'add_test(NAME output_intents_tests COMMAND output_intents_tests)\n' + test_anchor, 1)
p.write_text(s)
PY
git diff --check
